// Direct-rust NVML telemetry plus fail-closed CMP100 clock/power controls.
// No GPU reset, driver reload, Xorg, shell command, raw-register access, or crates.
// PCI identity is intentionally not queried: nvmlDeviceGetPciInfo_v3 has a
// versioned nvmlPciInfo_t ABI; a hand-written struct would not be safe here.
// Write identity is NVML name CMP 100-210 + CUDA capability 7.0; hbm-877 also
// pins the known-good driver and VBIOS.  All writes default to dry-run.
#![allow(non_snake_case)] // Keep the NVML C ABI field names recognizable.
use std::{env,ffi::{CStr,CString},os::raw::{c_char,c_int,c_uint,c_ulong,c_ulonglong},process::ExitCode,thread,time::Duration};
type D=*mut std::ffi::c_void; type R=c_int;
const OK:R=0;const NOT_SUPPORTED:R=3;const INSUFFICIENT:R=7;const MEM_CLOCK:c_uint=2;const TEMP_GPU:c_uint=0;const MEM_TEMP_FIELD:c_uint=82;const MEM_MAX_THRESHOLD:c_uint=2;
