 fn nvmlDeviceGetMemClkVfOffset(d:D,v:*mut c_int)->R;fn nvmlDeviceGetMemClkMinMaxVfOffset(d:D,lo:*mut c_int,hi:*mut c_int)->R;fn nvmlDeviceSetMemClkVfOffset(d:D,v:c_int)->R;fn nvmlDeviceGetGpcClkVfOffset(d:D,v:*mut c_int)->R;fn nvmlDeviceGetGpcClkMinMaxVfOffset(d:D,lo:*mut c_int,hi:*mut c_int)->R;fn nvmlDeviceSetGpcClkVfOffset(d:D,v:c_int)->R;
 fn nvmlDeviceGetClockInfo(d:D,c:c_uint,v:*mut c_uint)->R;fn nvmlDeviceGetMaxClockInfo(d:D,c:c_uint,v:*mut c_uint)->R;fn nvmlDeviceGetTemperature(d:D,s:c_uint,v:*mut c_uint)->R;fn nvmlDeviceGetPowerUsage(d:D,v:*mut c_uint)->R;fn nvmlDeviceGetPowerManagementLimit(d:D,v:*mut c_uint)->R;fn nvmlDeviceGetPowerManagementLimitConstraints(d:D,lo:*mut c_uint,hi:*mut c_uint)->R;fn nvmlDeviceGetPowerManagementDefaultLimit(d:D,v:*mut c_uint)->R;fn nvmlDeviceGetEnforcedPowerLimit(d:D,v:*mut c_uint)->R;fn nvmlDeviceGetTotalEnergyConsumption(d:D,v:*mut c_ulonglong)->R;fn nvmlDeviceSetPowerManagementLimit(d:D,v:c_uint)->R;
