fn es(r:R)->String{unsafe{CStr::from_ptr(nvmlErrorString(r)).to_string_lossy().into_owned()}}fn ck(r:R,what:&str)->Result<(),String>{if r==OK{Ok(())}else{Err(format!("{what}: {} ({r})",es(r)))}}
fn ds(f:unsafe extern "C" fn(D,*mut c_char,c_uint)->R,d:D,what:&str)->Result<String,String>{let mut b=[0i8;96];ck(unsafe{f(d,b.as_mut_ptr(),b.len()as c_uint)},what)?;Ok(unsafe{CStr::from_ptr(b.as_ptr()).to_string_lossy().into_owned()})}
fn name(d:D)->Result<String,String>{ds(nvmlDeviceGetName,d,"read GPU name")}fn uuid(d:D)->Result<String,String>{ds(nvmlDeviceGetUUID,d,"read GPU UUID")}fn vbios(d:D)->Result<String,String>{ds(nvmlDeviceGetVbiosVersion,d,"read VBIOS")}
fn driver()->Result<String,String>{let mut b=[0i8;96];ck(unsafe{nvmlSystemGetDriverVersion(b.as_mut_ptr(),b.len()as c_uint)},"read driver version")?;Ok(unsafe{CStr::from_ptr(b.as_ptr()).to_string_lossy().into_owned()})}
fn by_i(i:c_uint)->Result<D,String>{let mut d=std::ptr::null_mut();ck(unsafe{nvmlDeviceGetHandleByIndex_v2(i,&mut d)},"get GPU handle")?;Ok(d)}fn by_u(s:&str)->Result<D,String>{let c=CString::new(s).map_err(|_|"UUID contains NUL".to_string())?;let mut d=std::ptr::null_mut();ck(unsafe{nvmlDeviceGetHandleByUUID(c.as_ptr(),&mut d)},"get GPU by UUID")?;Ok(d)}
fn ri(d:D,g:unsafe extern "C" fn(D,*mut c_int)->R,w:&str)->Result<c_int,String>{let mut x=0;ck(unsafe{g(d,&mut x)},w)?;Ok(x)}fn ru(d:D,g:unsafe extern "C" fn(D,*mut c_uint)->R,w:&str)->Result<c_uint,String>{let mut x=0;ck(unsafe{g(d,&mut x)},w)?;Ok(x)}
fn cmp(d:D)->Result<(),String>{let n=name(d)?;let(mut ma,mut mi)=(0,0);ck(unsafe{nvmlDeviceGetCudaComputeCapability(d,&mut ma,&mut mi)},"read CUDA capability")?;if n!=CMP_NAME||ma!=7||mi!=0{Err(format!("refusing write: need NVML name {CMP_NAME:?} and CUDA capability 7.0; got {n:?}, {ma}.{mi}"))}else{Ok(())}}
fn profile_platform(d:D,untested:bool)->Result<(),String>{cmp(d)?;let(dr,vb)=(driver()?,vbios(d)?);if dr==PROFILE_DRIVER&&vb==PROFILE_VBIOS{Ok(())}else if untested{eprintln!("warning: untested hbm-877 platform driver={dr}, vbios={vb}; tested={PROFILE_DRIVER}/{PROFILE_VBIOS}");Ok(())}else{Err(format!("refusing untested hbm-877: driver={dr}, vbios={vb}; need {PROFILE_DRIVER}/{PROFILE_VBIOS}, or --allow-untested"))}}
fn val<'a>(a:&'a[String],flag:&str)->Result<Option<&'a str>,String>{let mut r=None;for(i,x)in a.iter().enumerate(){if x==flag{if r.is_some(){return Err(format!("{flag} specified more than once"))}let v=a.get(i+1).ok_or_else(||format!("missing value after {flag}"))?;if v.starts_with("--"){return Err(format!("missing value after {flag}"))}r=Some(v.as_str())}}Ok(r)}fn flag(a:&[String],x:&str)->bool{a.iter().any(|v|v==x)}fn req<'a>(a:&'a[String])->Result<&'a str,String>{val(a,"--uuid")?.ok_or_else(||"missing --uuid GPU-...".to_string())}
fn flags(a:&[String],values:&[&str],bools:&[&str])->Result<(),String>{let mut need=false;for x in a.iter().skip(2){if need{need=false;continue}if values.contains(&x.as_str()){need=true}else if !bools.contains(&x.as_str()){return Err(format!("unknown argument: {x}"))}}if need{Err("missing option value".into())}else{Ok(())}}
fn pi(s:&str,f:&str)->Result<c_int,String>{let x=s.parse::<i64>().map_err(|_|format!("{f} must be a base-10 integer"))?;c_int::try_from(x).map_err(|_|format!("{f} exceeds signed 32-bit range"))}fn pw(s:&str)->Result<c_uint,String>{let w=s.parse::<u64>().map_err(|_|"--watts must be a non-negative base-10 integer".to_string())?;let mw=w.checked_mul(1000).ok_or_else(||"--watts overflows milliwatts".to_string())?;c_uint::try_from(mw).map_err(|_|"--watts exceeds NVML range".to_string())}
#[derive(Clone,Copy)]enum K{Hbm,Core,Power}impl K{fn s(self)->&'static str{match self{K::Hbm=>"hbmOffset",K::Core=>"coreOffset",K::Power=>"powerLimitMilliwatts"}}}#[derive(Clone,Copy)]struct C{k:K,old:i64,new:i64}
fn range(d:D,k:K)->Result<(c_int,c_int),String>{let(mut lo,mut hi)=(0,0);let r=unsafe{match k{K::Hbm=>nvmlDeviceGetMemClkMinMaxVfOffset(d,&mut lo,&mut hi),K::Core=>nvmlDeviceGetGpcClkMinMaxVfOffset(d,&mut lo,&mut hi),K::Power=>unreachable!()}};ck(r,"read clock-offset constraints")?;Ok((lo,hi))}
fn po(d:D,k:K,new:c_int,bypass:bool)->Result<C,String>{let old=match k{K::Hbm=>ri(d,nvmlDeviceGetMemClkVfOffset,"read HBM offset")?,K::Core=>ri(d,nvmlDeviceGetGpcClkVfOffset,"read core offset")?,K::Power=>unreachable!()};let(lo,hi)=range(d,k)?;if(new<lo||new>hi)&&!bypass{return Err(format!("{} {new} outside NVML range {lo}..{hi}; use --allow-out-of-range only after independent validation",k.s()))}Ok(C{k,old:old as i64,new:new as i64})}
fn pp(d:D,new:c_uint)->Result<C,String>{let old=ru(d,nvmlDeviceGetPowerManagementLimit,"read power limit")?;let(mut lo,mut hi)=(0,0);ck(unsafe{nvmlDeviceGetPowerManagementLimitConstraints(d,&mut lo,&mut hi)},"read power constraints")?;if new<lo||new>hi{return Err(format!("power limit {} W outside NVML constraints {}..{} W",new as f64/1000.,lo as f64/1000.,hi as f64/1000.))}Ok(C{k:K::Power,old:old as i64,new:new as i64})}
fn one(d:D,c:C)->Result<(),String>{let r=unsafe{match c.k{K::Hbm=>nvmlDeviceSetMemClkVfOffset(d,c.new as c_int),K::Core=>nvmlDeviceSetGpcClkVfOffset(d,c.new as c_int),K::Power=>nvmlDeviceSetPowerManagementLimit(d,c.new as c_uint)}};ck(r,&format!("set {}",c.k.s()))?;let got=match c.k{K::Hbm=>ri(d,nvmlDeviceGetMemClkVfOffset,"read HBM offset after write")?as i64,K::Core=>ri(d,nvmlDeviceGetGpcClkVfOffset,"read core offset after write")?as i64,K::Power=>ru(d,nvmlDeviceGetPowerManagementLimit,"read power limit after write")?as i64};if got!=c.new{Err(format!("{} readback mismatch: requested {}, got {}",c.k.s(),c.new,got))}else{Ok(())}}
fn rollback(d:D,cs:&[C])->String{let mut e=Vec::new();for c in cs.iter().rev(){if let Err(x)=one(d,C{new:c.old,..*c}){e.push(x)}}if e.is_empty(){"rollback=ok".into()}else{format!("rollback_failed={}",e.join("; "))}}
fn jcs(cs:&[C])->String{cs.iter().map(|c|format!("{{\"setting\":\"{}\",\"previous\":{},\"requested\":{}}}",c.k.s(),c.old,c.new)).collect::<Vec<_>>().join(",")}
fn wait_hbm_clock(d:D)->Result<(),String>{let mut mhz=0;for attempt in 0..=20{ck(unsafe{nvmlDeviceGetClockInfo(d,MEM_CLOCK,&mut mhz)},"read effective HBM clock")?;if mhz==HBM_CLOCK{return Ok(())}if attempt<20{thread::sleep(Duration::from_millis(100))}}Err(format!("effective HBM clock {mhz} MHz after 2 seconds, expected {HBM_CLOCK} MHz"))}
fn exec(d:D,u:&str,cmd:&str,cs:&[C],apply:bool,clock:bool)->Result<(),String>{if !apply{println!("{{\"command\":\"{cmd}\",\"uuid\":\"{u}\",\"dryRun\":true,\"requires\":\"--apply\",\"changes\":[{}]}}",jcs(cs));return Ok(())}let mut done=Vec::new();for c in cs{if let Err(e)=one(d,*c){let mut affected=done.clone();affected.push(*c);return Err(format!("{cmd} failed: {e}; {}",rollback(d,&affected)))}done.push(*c)}if clock{if let Err(e)=wait_hbm_clock(d){return Err(format!("hbm-877 verification failed: {e}; {}",rollback(d,&done)))}}println!("{{\"command\":\"{cmd}\",\"uuid\":\"{u}\",\"applied\":true,\"changes\":[{}]}}",jcs(cs));Ok(())}
fn fields(d:D)->String{let mut o=Vec::new();for id in 1..=199{let mut f=Field{fieldId:id,scopeId:0,timestamp:i64::MIN,latencyUsec:i64::MIN,valueType:6,nvmlReturn:999,value:V{ullVal:0xdeadbeefdeadbeef}};let outer=unsafe{nvmlDeviceGetFieldValues(d,1,&mut f)};let same=f.nvmlReturn==999&&f.valueType==6&&f.timestamp==i64::MIN;let(st,v)=if outer!=OK{("error","null".into())}else if same{("unreturned","null".into())}else if f.nvmlReturn==NOT_SUPPORTED{("unsupported","null".into())}else if f.nvmlReturn!=OK{("field_error","null".into())}else{("driver_reported",fv(f.valueType,&f.value))};o.push(format!("{{\"id\":{id},\"value\":{v},\"valueType\":{},\"nvmlReturn\":{},\"outerReturn\":{outer},\"reliability\":\"{st}\",\"timestampUs\":{},\"latencyUs\":{}}}",f.valueType,f.nvmlReturn,if f.timestamp==i64::MIN{"null".into()}else{format!("\"{}\"",f.timestamp)},if f.latencyUsec==i64::MIN{"null".into()}else{format!("\"{}\"",f.latencyUsec)}))}o.join(",")}
fn fv(t:c_int,v:&V)->String{unsafe{match t{0=>format!("{}",v.dVal),1=>format!("{}",v.uiVal),2=>format!("\"{}\"",v.ulVal),3=>format!("\"{}\"",v.ullVal),4=>format!("\"{}\"",v.sllVal),5=>format!("{}",v.siVal),_=>"null".into()}}}
fn samples(d:D,t:c_int)->String{let(mut vt,mut n)=(6,0);let probe=unsafe{nvmlDeviceGetSamples(d,t,0,&mut vt,&mut n,std::ptr::null_mut())};if probe!=OK{return format!("{{\"type\":{t},\"probeReturn\":{probe},\"samples\":[]}}")}if n>MAX_ENTRIES{return format!("{{\"type\":{t},\"probeReturn\":{probe},\"error\":\"sample_count_cap\",\"samples\":[]}}")}for attempt in 0..2{let cap=n;let mut v=Vec::<Sample>::with_capacity(cap as usize);let mut got=cap;let read=unsafe{nvmlDeviceGetSamples(d,t,0,&mut vt,&mut got,v.as_mut_ptr())};if read==OK&&got<=cap{unsafe{v.set_len(got as usize)}let rows=v.iter().map(|s|format!("{{\"timestampUs\":\"{}\",\"value\":{}}}",s.timestamp,fv(vt,&s.value))).collect::<Vec<_>>().join(",");return format!("{{\"type\":{t},\"probeReturn\":{probe},\"readReturn\":{read},\"valueType\":{vt},\"samples\":[{rows}]}}")};if read==INSUFFICIENT&&got>cap&&got<=MAX_ENTRIES&&attempt==0{n=got;continue}return format!("{{\"type\":{t},\"probeReturn\":{probe},\"readReturn\":{read},\"returnedCount\":{got},\"samples\":[]}}")}unreachable!()}
fn pcall(d:D,g:bool,n:*mut c_uint,v:*mut Proc)->R{unsafe{if g{nvmlDeviceGetGraphicsRunningProcesses_v3(d,n,v)}else{nvmlDeviceGetComputeRunningProcesses_v3(d,n,v)}}}fn procs(d:D,g:bool)->String{let mut n=0;let probe=pcall(d,g,&mut n,std::ptr::null_mut());if probe!=OK&&probe!=INSUFFICIENT{return format!("{{\"probeReturn\":{probe},\"entries\":[]}}")}if n>MAX_ENTRIES{return "{\"error\":\"process_count_cap\",\"entries\":[]}".into()}for attempt in 0..2{let cap=match n.checked_add(4){Some(x)if x<=MAX_ENTRIES=>x,_=>return "{\"error\":\"process_count_cap\",\"entries\":[]}".into()};let mut v=Vec::<Proc>::with_capacity(cap as usize);let mut got=cap;let read=pcall(d,g,&mut got,v.as_mut_ptr());if read==OK&&got<=cap{unsafe{v.set_len(got as usize)}let rows=v.iter().map(|p|format!("{{\"pid\":{},\"usedGpuMemoryBytes\":{},\"gpuInstanceId\":{},\"computeInstanceId\":{}}}",p.pid,if p.usedGpuMemory==u64::MAX{"null".into()}else{format!("\"{}\"",p.usedGpuMemory)},if p.gpuInstanceId==u32::MAX{"null".into()}else{p.gpuInstanceId.to_string()},if p.computeInstanceId==u32::MAX{"null".into()}else{p.computeInstanceId.to_string()})).collect::<Vec<_>>().join(",");return format!("{{\"probeReturn\":{probe},\"readReturn\":{read},\"entries\":[{rows}]}}")};if read==INSUFFICIENT&&got>cap&&got<=MAX_ENTRIES&&attempt==0{n=got;continue}return format!("{{\"probeReturn\":{probe},\"readReturn\":{read},\"returnedCount\":{got},\"entries\":[]}}")}unreachable!()}
fn list(n:c_uint)->Result<(),String>{let dr=driver()?;let mut o=Vec::new();for i in 0..n{let d=by_i(i)?;let nm=name(d)?;let u=uuid(d)?;let vb=vbios(d)?;let(mut ma,mut mi)=(0,0);ck(unsafe{nvmlDeviceGetCudaComputeCapability(d,&mut ma,&mut mi)},"read CUDA capability")?;o.push(format!("{{\"index\":{i},\"name\":\"{nm}\",\"uuid\":\"{u}\",\"vbios\":\"{vb}\",\"cudaComputeCapability\":\"{ma}.{mi}\",\"writeTargetCmp100_210\":{},\"pciIdVerification\":\"not_collected: nvmlPciInfo_v3 ABI intentionally omitted; write identity uses NVML name plus CUDA capability\"}}",nm==CMP_NAME&&ma==7&&mi==0))}println!("{{\"schemaVersion\":3,\"driverVersion\":\"{dr}\",\"gpus\":[{}]}}",o.join(","));Ok(())}
fn telemetry(n:c_uint,json:bool)->Result<(),String>{macro_rules! get{($call:expr,$what:literal)=>{ck(unsafe{$call},$what)?};}let mut o=Vec::new();for i in 0..n{let d=by_i(i)?;let(mut mo,mut go,mut gmin,mut gmax,mut mm,mut mx)=(0,0,0,0,0,0);let(mut c0,mut c1,mut c2,mut c3,mut x0,mut x1,mut x2,mut x3)=(0,0,0,0,0,0,0,0);let(mut tg,mut hm,mut tsh,mut tsl,mut tmax)=(0,0,0,0,0);let(mut pw0,mut pl,mut pd,mut pe,mut plo,mut phi)=(0,0,0,0,0,0);let mut en=0;let mut u=Util{gpu:0,memory:0};let mut m=Mem{total:0,free:0,used:0};let mut b=Bar1{total:0,free:0,used:0};let(mut ps,mut th,mut ths)=(0,0,0);let(mut pg,mut px,mut pgm,mut pxm,mut ptx,mut prx,mut rep)=(0,0,0,0,0,0,0);let(mut cores,mut bus,mut arch,mut ma,mut mi)=(0,0,0,0,0);let mut f=Field{fieldId:MEM_TEMP_FIELD,scopeId:0,timestamp:0,latencyUsec:0,valueType:0,nvmlReturn:-1,value:V{ullVal:0}};get!(nvmlDeviceGetMemClkVfOffset(d,&mut mo),"read HBM offset");get!(nvmlDeviceGetGpcClkVfOffset(d,&mut go),"read core offset");get!(nvmlDeviceGetGpcClkMinMaxVfOffset(d,&mut gmin,&mut gmax),"read core offset constraints");get!(nvmlDeviceGetMemClkMinMaxVfOffset(d,&mut mm,&mut mx),"read HBM offset constraints");get!(nvmlDeviceGetClockInfo(d,0,&mut c0),"read graphics clock");get!(nvmlDeviceGetClockInfo(d,1,&mut c1),"read SM clock");get!(nvmlDeviceGetClockInfo(d,2,&mut c2),"read HBM clock");get!(nvmlDeviceGetClockInfo(d,3,&mut c3),"read video clock");get!(nvmlDeviceGetMaxClockInfo(d,0,&mut x0),"read max graphics clock");get!(nvmlDeviceGetMaxClockInfo(d,1,&mut x1),"read max SM clock");get!(nvmlDeviceGetMaxClockInfo(d,2,&mut x2),"read max HBM clock");get!(nvmlDeviceGetMaxClockInfo(d,3,&mut x3),"read max video clock");get!(nvmlDeviceGetTemperature(d,TEMP_GPU,&mut tg),"read GPU temperature");get!(nvmlDeviceGetTemperatureThreshold(d,0,&mut tsh),"read GPU shutdown temperature");get!(nvmlDeviceGetTemperatureThreshold(d,1,&mut tsl),"read GPU slowdown temperature");get!(nvmlDeviceGetTemperatureThreshold(d,MEM_MAX_THRESHOLD,&mut hm),"read HBM maximum temperature");get!(nvmlDeviceGetTemperatureThreshold(d,3,&mut tmax),"read GPU maximum temperature");get!(nvmlDeviceGetFieldValues(d,1,&mut f),"read HBM temperature field");if f.nvmlReturn!=OK{return Err(format!("HBM temperature field: {} ({})",es(f.nvmlReturn),f.nvmlReturn))}get!(nvmlDeviceGetPowerUsage(d,&mut pw0),"read power usage");get!(nvmlDeviceGetPowerManagementLimit(d,&mut pl),"read power limit");get!(nvmlDeviceGetPowerManagementDefaultLimit(d,&mut pd),"read default power limit");get!(nvmlDeviceGetEnforcedPowerLimit(d,&mut pe),"read enforced power limit");get!(nvmlDeviceGetPowerManagementLimitConstraints(d,&mut plo,&mut phi),"read power constraints");get!(nvmlDeviceGetTotalEnergyConsumption(d,&mut en),"read total energy");get!(nvmlDeviceGetUtilizationRates(d,&mut u),"read utilization");get!(nvmlDeviceGetMemoryInfo(d,&mut m),"read VRAM");get!(nvmlDeviceGetBAR1MemoryInfo(d,&mut b),"read BAR1 memory");get!(nvmlDeviceGetPerformanceState(d,&mut ps),"read performance state");get!(nvmlDeviceGetCurrentClocksThrottleReasons(d,&mut th),"read throttle state");get!(nvmlDeviceGetSupportedClocksThrottleReasons(d,&mut ths),"read supported throttles");get!(nvmlDeviceGetCurrPcieLinkGeneration(d,&mut pg),"read current PCIe generation");get!(nvmlDeviceGetCurrPcieLinkWidth(d,&mut px),"read current PCIe width");get!(nvmlDeviceGetMaxPcieLinkGeneration(d,&mut pgm),"read maximum PCIe generation");get!(nvmlDeviceGetMaxPcieLinkWidth(d,&mut pxm),"read maximum PCIe width");get!(nvmlDeviceGetPcieThroughput(d,0,&mut ptx),"read PCIe TX");get!(nvmlDeviceGetPcieThroughput(d,1,&mut prx),"read PCIe RX");get!(nvmlDeviceGetPcieReplayCounter(d,&mut rep),"read PCIe replay counter");get!(nvmlDeviceGetNumGpuCores(d,&mut cores),"read GPU core count");get!(nvmlDeviceGetMemoryBusWidth(d,&mut bus),"read memory bus width");get!(nvmlDeviceGetCudaComputeCapability(d,&mut ma,&mut mi),"read CUDA capability");get!(nvmlDeviceGetArchitecture(d,&mut arch),"read architecture");let tm=unsafe{f.value.uiVal as i64};o.push(format!("{{\"index\":{i},\"name\":\"{}\",\"uuid\":\"{}\",\"status\":{{\"hbmFieldNvmlReturn\":{},\"hbmOffsetRangeReliability\":\"suspect_on_cmp\",\"gpcOffsetRangeReliability\":\"suspect_on_cmp\",\"pciIdVerification\":\"not_collected: ABI-safe direct-rust NVML choice\"}},\"offsets\":{{\"hbmRaw\":{mo},\"coreRaw\":{go},\"hbmRangeRaw\":[{mm},{mx}],\"coreRangeRaw\":[{gmin},{gmax}]}},\"clocksMHz\":{{\"graphics\":{c0},\"sm\":{c1},\"memory\":{c2},\"video\":{c3},\"maxGraphics\":{x0},\"maxSm\":{x1},\"maxMemoryStock\":{x2},\"maxVideo\":{x3}}},\"thermalC\":{{\"gpu\":{tg},\"hbm\":{tm},\"shutdown\":{tsh},\"slowdown\":{tsl},\"hbmMax\":{hm},\"gpuMax\":{tmax}}},\"power\":{{\"instantW\":{:.3},\"limitW\":{:.3},\"defaultLimitW\":{:.3},\"enforcedLimitW\":{:.3},\"minLimitW\":{:.3},\"maxLimitW\":{:.3},\"energyMilliJoules\":\"{}\"}},\"utilizationPct\":{{\"gpu\":{},\"memory\":{}}},\"memory\":{{\"vramUsedBytes\":\"{}\",\"vramFreeBytes\":\"{}\",\"vramTotalBytes\":\"{}\",\"bar1UsedBytes\":\"{}\",\"bar1FreeBytes\":\"{}\",\"bar1TotalBytes\":\"{}\"}},\"performance\":{{\"pstate\":{ps},\"throttleActiveMask\":{th},\"throttleSupportedMask\":{ths}}},\"pcie\":{{\"currentGen\":{pg},\"currentWidth\":{px},\"maxGen\":{pgm},\"maxWidth\":{pxm},\"txKBps\":{ptx},\"rxKBps\":{prx},\"replayCounter\":{rep}}},\"static\":{{\"architectureEnum\":{arch},\"gpuCores\":{cores},\"memoryBusWidthBits\":{bus},\"cudaComputeCapability\":\"{ma}.{mi}\"}}}}",name(d)?,uuid(d)?,f.nvmlReturn,pw0 as f64/1000.,pl as f64/1000.,pd as f64/1000.,pe as f64/1000.,plo as f64/1000.,phi as f64/1000.,en,u.gpu,u.memory,m.used,m.free,m.total,b.used,b.free,b.total))}if json{println!("{{\"schemaVersion\":3,\"gpus\":[{}]}}",o.join(","))}else{for x in o{println!("{x}")}}Ok(())}
fn tune(a:&[String])->Result<(),String>{flags(a,&["--uuid","--hbm-offset","--core-offset","--watts"],&["--apply","--allow-out-of-range"])?;let u=req(a)?;let h=val(a,"--hbm-offset")?.map(|x|pi(x,"--hbm-offset")).transpose()?;let c=val(a,"--core-offset")?.map(|x|pi(x,"--core-offset")).transpose()?;let w=val(a,"--watts")?.map(pw).transpose()?;if h.is_none()&&c.is_none()&&w.is_none(){return Err("tune requires --hbm-offset, --core-offset, or --watts".into())}let d=by_u(u)?;cmp(d)?;let b=flag(a,"--allow-out-of-range");let mut cs=Vec::new();if let Some(x)=h{cs.push(po(d,K::Hbm,x,b)?)}if let Some(x)=c{cs.push(po(d,K::Core,x,b)?)}if let Some(x)=w{cs.push(pp(d,x)?)}exec(d,u,"tune",&cs,flag(a,"--apply"),false)}
fn profile(a:&[String])->Result<(),String>{flags(a,&["--uuid","--name"],&["--apply","--allow-untested"])?;let u=req(a)?;if val(a,"--name")?.ok_or_else(||"missing --name hbm-877".to_string())? !="hbm-877"{return Err("supported profile: hbm-877".into())}let d=by_u(u)?;profile_platform(d,flag(a,"--allow-untested"))?;let old=ri(d,nvmlDeviceGetMemClkVfOffset,"read HBM offset")?;exec(d,u,"profile:hbm-877",&[C{k:K::Hbm,old:old as i64,new:HBM_OFFSET as i64}],flag(a,"--apply"),true)}
fn reset(a:&[String])->Result<(),String>{flags(a,&["--uuid"],&["--hbm","--core","--power","--apply"])?;let u=req(a)?;let(h,c,p)=(flag(a,"--hbm"),flag(a,"--core"),flag(a,"--power"));if !h&&!c&&!p{return Err("reset requires --hbm, --core, or --power".into())}let d=by_u(u)?;cmp(d)?;let mut cs=Vec::new();if h{cs.push(C{k:K::Hbm,old:ri(d,nvmlDeviceGetMemClkVfOffset,"read HBM offset")?as i64,new:0})}if c{cs.push(C{k:K::Core,old:ri(d,nvmlDeviceGetGpcClkVfOffset,"read core offset")?as i64,new:0})}if p{let old=ru(d,nvmlDeviceGetPowerManagementLimit,"read power limit")?;let def=ru(d,nvmlDeviceGetPowerManagementDefaultLimit,"read default power limit")?;let(mut lo,mut hi)=(0,0);ck(unsafe{nvmlDeviceGetPowerManagementLimitConstraints(d,&mut lo,&mut hi)},"read power constraints")?;if def<lo||def>hi{return Err(format!("default power limit {def} mW outside constraints {lo}..{hi}"))}cs.push(C{k:K::Power,old:old as i64,new:def as i64})}exec(d,u,"reset",&cs,flag(a,"--apply"),false)}
fn usage(p:&str){eprintln!("Usage:\n  {p} list\n  {p} status [--json]  # alias for telemetry\n  {p} telemetry [--json] | fields | samples | processes\n  {p} profile --uuid GPU-... --name hbm-877 [--apply] [--allow-untested]\n  {p} tune --uuid GPU-... [--hbm-offset N] [--core-offset N] [--watts W] [--apply] [--allow-out-of-range]\n  {p} reset --uuid GPU-... [--hbm] [--core] [--power] [--apply]\nWrites are dry-run unless --apply. PCI ID is deliberately omitted; see source header.")}
fn run(a:&[String])->Result<(),String>{let mut n=0;ck(unsafe{nvmlDeviceGetCount_v2(&mut n)},"get GPU count")?;match a.get(1).map(String::as_str).unwrap_or(""){"list"=>{flags(a,&[],&[])?;list(n)},"status"=>{flags(a,&[],&["--json"])?;telemetry(n,flag(a,"--json"))},"telemetry"=>{flags(a,&[],&["--json"])?;telemetry(n,flag(a,"--json"))},"fields"=>{flags(a,&[],&[])?;let mut o=Vec::new();for i in 0..n{let d=by_i(i)?;o.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"rawFieldValues\":[{}]}}",uuid(d)?,fields(d)))}println!("{{\"schemaVersion\":3,\"gpus\":[{}]}}",o.join(","));Ok(())},"samples"=>{flags(a,&[],&[])?;let mut o=Vec::new();for i in 0..n{let d=by_i(i)?;let rows=(0..=9).map(|t|samples(d,t)).collect::<Vec<_>>().join(",");o.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"sampleStreams\":[{rows}]}}",uuid(d)?))}println!("{{\"schemaVersion\":3,\"gpus\":[{}]}}",o.join(","));Ok(())},"processes"=>{flags(a,&[],&[])?;let mut o=Vec::new();for i in 0..n{let d=by_i(i)?;o.push(format!("{{\"index\":{i},\"uuid\":\"{}\",\"compute\":{},\"graphics\":{}}}",uuid(d)?,procs(d,false),procs(d,true)))}println!("{{\"schemaVersion\":3,\"gpus\":[{}]}}",o.join(","));Ok(())},"profile"=>profile(a),"tune"=>tune(a),"reset"=>reset(a),_=>{usage(&a[0]);Err("missing or unsupported command".into())}}}
fn main()->ExitCode{let a=env::args().collect::<Vec<_>>();let init=unsafe{nvmlInit_v2()};if let Err(e)=ck(init,"NVML init"){eprintln!("error: {e}");return ExitCode::FAILURE}let r=run(&a);let shut=unsafe{nvmlShutdown()};match r{Err(e)=>{eprintln!("error: {e}");if shut!=OK{eprintln!("error: NVML shutdown: {} ({shut})",es(shut))}ExitCode::FAILURE},Ok(())=>match ck(shut,"NVML shutdown"){Ok(())=>ExitCode::SUCCESS,Err(e)=>{eprintln!("error: {e}");ExitCode::FAILURE}}}}
